.shield-wrap { 
  position: relative; width: 120px; height: 140px; 
  display: flex; align-items: center; justify-content: center; 
}
.shield-svg { 
  width: 100%; height: 100%; filter: drop-shadow(0 0 25px rgba(0, 255, 204, 0.6)); 
}
.shield-path { 
  fill: rgba(0,255,204,0.05); stroke: #00ffcc; stroke-width: 4; 
  stroke-linejoin: round; stroke-dasharray: 400; stroke-dashoffset: 400; 
  animation: drawShield 2s ease-in-out forwards; 
}
.shield-check { 
  fill: none; stroke: #fff; stroke-width: 8; stroke-linecap: round; 
  stroke-linejoin: round; stroke-dasharray: 100; stroke-dashoffset: 100; 
  animation: drawCheck 0.6s ease-out 1.8s forwards; 
}
.offline-txt {
  position: absolute; bottom: -40px; color: #00ffcc; font-family: sans-serif;
  font-weight: bold; letter-spacing: 2px; opacity: 0;
  animation: fadeArea 1s ease-out 2.5s forwards;
}
@keyframes drawShield { to { stroke-dashoffset: 0; fill: rgba(0,255,204,0.2); } }
@keyframes drawCheck { to { stroke-dashoffset: 0; } }
@keyframes fadeArea { to { opacity: 1; } }
